-- READ-ONLY; exact timestamp union, fixed UTC year; tolerance 0.001 on raw ratios.
SELECT
 COUNT(*) AS `union_keys`,
 SUM(a0.usUnits=17 AND a1.usUnits=17 AND a2.usUnits=16) AS `expected_unit_triplets`,
 SUM(a0.usUnits=17 AND a1.usUnits=17 AND a2.usUnits=16 AND a0.interval=5 AND a1.interval=5 AND a2.interval=5) AS `expected_unit_interval_triplets`,
 SUM(a0.`windSpeed` IS NOT NULL AND a1.`windSpeed` IS NOT NULL AND a0.`windSpeed`=a1.`windSpeed`) AS `windSpeed_source_equal`,
 SUM(a0.`windSpeed` IS NOT NULL AND a1.`windSpeed` IS NOT NULL AND a0.`windSpeed`=a1.`windSpeed` AND a2.`dateTime` IS NOT NULL AND a2.`windSpeed` IS NULL) AS `windSpeed_target_null`,
 SUM(a0.`windSpeed` IS NOT NULL AND a1.`windSpeed` IS NOT NULL AND a0.`windSpeed`=a1.`windSpeed` AND a2.`dateTime` IS NULL) AS `windSpeed_target_row_absent`,
 SUM(a0.`windSpeed` IS NOT NULL AND a1.`windSpeed` IS NOT NULL AND a0.`windSpeed`=a1.`windSpeed` AND a0.`windSpeed`<>0 AND a2.`windSpeed` IS NOT NULL) AS `windSpeed_target_nonzero_pairs`,
 SUM(a0.`windSpeed` IS NOT NULL AND a1.`windSpeed` IS NOT NULL AND a0.`windSpeed`=a1.`windSpeed` AND a0.`windSpeed`<>0 AND a2.`windSpeed` IS NOT NULL AND ABS(a2.`windSpeed`/a0.`windSpeed`-3.6)<0.001) AS `windSpeed_expected_factor`,
 SUM(a0.`windSpeed` IS NOT NULL AND a1.`windSpeed` IS NOT NULL AND a0.`windSpeed`=a1.`windSpeed` AND a0.`windSpeed`<>0 AND a2.`windSpeed` IS NOT NULL AND ABS(a2.`windSpeed`/a0.`windSpeed`-1)<0.001) AS `windSpeed_ratio_1`,
 SUM(a0.`windSpeed` IS NOT NULL AND a1.`windSpeed` IS NOT NULL AND a0.`windSpeed`=a1.`windSpeed` AND a0.`windSpeed`<>0 AND a2.`windSpeed` IS NOT NULL AND ABS(a2.`windSpeed`/a0.`windSpeed`-3.6)>=0.001 AND ABS(a2.`windSpeed`/a0.`windSpeed`-1)>=0.001) AS `windSpeed_other_factor`,
 SUM(a0.`windGust` IS NOT NULL AND a1.`windGust` IS NOT NULL AND a0.`windGust`=a1.`windGust`) AS `windGust_source_equal`,
 SUM(a0.`windGust` IS NOT NULL AND a1.`windGust` IS NOT NULL AND a0.`windGust`=a1.`windGust` AND a2.`dateTime` IS NOT NULL AND a2.`windGust` IS NULL) AS `windGust_target_null`,
 SUM(a0.`windGust` IS NOT NULL AND a1.`windGust` IS NOT NULL AND a0.`windGust`=a1.`windGust` AND a2.`dateTime` IS NULL) AS `windGust_target_row_absent`,
 SUM(a0.`windGust` IS NOT NULL AND a1.`windGust` IS NOT NULL AND a0.`windGust`=a1.`windGust` AND a0.`windGust`<>0 AND a2.`windGust` IS NOT NULL) AS `windGust_target_nonzero_pairs`,
 SUM(a0.`windGust` IS NOT NULL AND a1.`windGust` IS NOT NULL AND a0.`windGust`=a1.`windGust` AND a0.`windGust`<>0 AND a2.`windGust` IS NOT NULL AND ABS(a2.`windGust`/a0.`windGust`-3.6)<0.001) AS `windGust_expected_factor`,
 SUM(a0.`windGust` IS NOT NULL AND a1.`windGust` IS NOT NULL AND a0.`windGust`=a1.`windGust` AND a0.`windGust`<>0 AND a2.`windGust` IS NOT NULL AND ABS(a2.`windGust`/a0.`windGust`-1)<0.001) AS `windGust_ratio_1`,
 SUM(a0.`windGust` IS NOT NULL AND a1.`windGust` IS NOT NULL AND a0.`windGust`=a1.`windGust` AND a0.`windGust`<>0 AND a2.`windGust` IS NOT NULL AND ABS(a2.`windGust`/a0.`windGust`-3.6)>=0.001 AND ABS(a2.`windGust`/a0.`windGust`-1)>=0.001) AS `windGust_other_factor`,
 SUM(a0.`rain` IS NOT NULL AND a1.`rain` IS NOT NULL AND a0.`rain`=a1.`rain`) AS `rain_source_equal`,
 SUM(a0.`rain` IS NOT NULL AND a1.`rain` IS NOT NULL AND a0.`rain`=a1.`rain` AND a2.`dateTime` IS NOT NULL AND a2.`rain` IS NULL) AS `rain_target_null`,
 SUM(a0.`rain` IS NOT NULL AND a1.`rain` IS NOT NULL AND a0.`rain`=a1.`rain` AND a2.`dateTime` IS NULL) AS `rain_target_row_absent`,
 SUM(a0.`rain` IS NOT NULL AND a1.`rain` IS NOT NULL AND a0.`rain`=a1.`rain` AND a0.`rain`<>0 AND a2.`rain` IS NOT NULL) AS `rain_target_nonzero_pairs`,
 SUM(a0.`rain` IS NOT NULL AND a1.`rain` IS NOT NULL AND a0.`rain`=a1.`rain` AND a0.`rain`<>0 AND a2.`rain` IS NOT NULL AND ABS(a2.`rain`/a0.`rain`-0.1)<0.001) AS `rain_expected_factor`,
 SUM(a0.`rain` IS NOT NULL AND a1.`rain` IS NOT NULL AND a0.`rain`=a1.`rain` AND a0.`rain`<>0 AND a2.`rain` IS NOT NULL AND ABS(a2.`rain`/a0.`rain`-1)<0.001) AS `rain_ratio_1`,
 SUM(a0.`rain` IS NOT NULL AND a1.`rain` IS NOT NULL AND a0.`rain`=a1.`rain` AND a0.`rain`<>0 AND a2.`rain` IS NOT NULL AND ABS(a2.`rain`/a0.`rain`-0.1)>=0.001 AND ABS(a2.`rain`/a0.`rain`-1)>=0.001) AS `rain_other_factor`,
 SUM(a0.`rainRate` IS NOT NULL AND a1.`rainRate` IS NOT NULL AND a0.`rainRate`=a1.`rainRate`) AS `rainRate_source_equal`,
 SUM(a0.`rainRate` IS NOT NULL AND a1.`rainRate` IS NOT NULL AND a0.`rainRate`=a1.`rainRate` AND a2.`dateTime` IS NOT NULL AND a2.`rainRate` IS NULL) AS `rainRate_target_null`,
 SUM(a0.`rainRate` IS NOT NULL AND a1.`rainRate` IS NOT NULL AND a0.`rainRate`=a1.`rainRate` AND a2.`dateTime` IS NULL) AS `rainRate_target_row_absent`,
 SUM(a0.`rainRate` IS NOT NULL AND a1.`rainRate` IS NOT NULL AND a0.`rainRate`=a1.`rainRate` AND a0.`rainRate`<>0 AND a2.`rainRate` IS NOT NULL) AS `rainRate_target_nonzero_pairs`,
 SUM(a0.`rainRate` IS NOT NULL AND a1.`rainRate` IS NOT NULL AND a0.`rainRate`=a1.`rainRate` AND a0.`rainRate`<>0 AND a2.`rainRate` IS NOT NULL AND ABS(a2.`rainRate`/a0.`rainRate`-0.1)<0.001) AS `rainRate_expected_factor`,
 SUM(a0.`rainRate` IS NOT NULL AND a1.`rainRate` IS NOT NULL AND a0.`rainRate`=a1.`rainRate` AND a0.`rainRate`<>0 AND a2.`rainRate` IS NOT NULL AND ABS(a2.`rainRate`/a0.`rainRate`-1)<0.001) AS `rainRate_ratio_1`,
 SUM(a0.`rainRate` IS NOT NULL AND a1.`rainRate` IS NOT NULL AND a0.`rainRate`=a1.`rainRate` AND a0.`rainRate`<>0 AND a2.`rainRate` IS NOT NULL AND ABS(a2.`rainRate`/a0.`rainRate`-0.1)>=0.001 AND ABS(a2.`rainRate`/a0.`rainRate`-1)>=0.001) AS `rainRate_other_factor`
FROM (SELECT `dateTime` FROM `old_weewx`.`archive` WHERE `dateTime` >= 1230768000 AND `dateTime` < 1262304000 UNION SELECT `dateTime` FROM `weewx_WH1080`.`archive` WHERE `dateTime` >= 1230768000 AND `dateTime` < 1262304000 UNION SELECT `dateTime` FROM `pocasi-loucka.eu_old`.`archive` WHERE `dateTime` >= 1230768000 AND `dateTime` < 1262304000) k
LEFT JOIN `old_weewx`.`archive` a0 ON a0.`dateTime`=k.`dateTime` LEFT JOIN `weewx_WH1080`.`archive` a1 ON a1.`dateTime`=k.`dateTime` LEFT JOIN `pocasi-loucka.eu_old`.`archive` a2 ON a2.`dateTime`=k.`dateTime`;
